import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import stat
import sys
import tarfile

def unique_object(pairs):
    result = {}
    for name, value in pairs:
        if name in result:
            raise ValueError('Duplicate JSON key: ' + name)
        result[name] = value
    return result

def safe_path(name):
    path = PurePosixPath(name)
    if not name or path.is_absolute() or path.as_posix() != name:
        raise ValueError('Unsafe path: ' + repr(name))
    if any(part in ('.', '..') for part in path.parts):
        raise ValueError('Unsafe path: ' + repr(name))
    if '\\' in name or any(ord(char) < 32 or ord(char) == 127 for char in name):
        raise ValueError('Unsafe path: ' + repr(name))
    return path

def restore(archive_path, manifest_path, destination):
    manifest = json.loads(Path(manifest_path).read_bytes(), object_pairs_hook=unique_object)
    if len(manifest) != 1908:
        raise ValueError('The manifest count differs.')
    for name, identity in manifest.items():
        path = safe_path(name)
        if any(parent.as_posix() in manifest for parent in path.parents):
            raise ValueError('A source path also names a parent file.')
        if set(identity) != {'bytes', 'sha256'} or type(identity['bytes']) is not int:
            raise ValueError('The manifest identity schema differs.')
        if identity['bytes'] < 0 or len(identity['sha256']) != 64:
            raise ValueError('The manifest identity is invalid.')
        int(identity['sha256'], 16)
    destination = Path(destination)
    if destination.exists() or destination.is_symlink():
        raise ValueError('The restore destination must not exist.')
    with tarfile.open(archive_path, 'r:gz') as archive:
        members = archive.getmembers()
        names = [member.name for member in members]
        if len(names) != len(set(names)) or set(names) != set(manifest):
            raise ValueError('The archive path set differs.')
        for member in members:
            safe_path(member.name)
            if not member.isfile() or member.linkname or member.sparse is not None:
                raise ValueError('The archive member is not a complete regular file.')
            if member.size != manifest[member.name]['bytes']:
                raise ValueError('The archive byte count differs.')
            if member.mode & ~0o777 or member.uid or member.gid or member.mtime:
                raise ValueError('The archive metadata differs.')
            if member.uname or member.gname:
                raise ValueError('The archive owner metadata differs.')
        destination.mkdir()
        total = 0
        for member in members:
            payload = archive.extractfile(member).read()
            if hashlib.sha256(payload).hexdigest() != manifest[member.name]['sha256']:
                raise ValueError('The archive payload hash differs: ' + member.name)
            target = destination.joinpath(*safe_path(member.name).parts)
            target.parent.mkdir(parents=True, exist_ok=True)
            with target.open('xb') as stream:
                stream.write(payload)
            target.chmod(member.mode)
            total += len(payload)
    restored = set()
    for directory, folders, files in os.walk(destination, followlinks=False):
        for name in folders + files:
            if (Path(directory) / name).is_symlink():
                raise ValueError('The restored tree contains a link.')
        for name in files:
            path = Path(directory) / name
            restored.add(path.relative_to(destination).as_posix())
    if restored != set(manifest):
        raise ValueError('The restored path set differs.')
    modes = {member.name: member.mode for member in members}
    for name, identity in manifest.items():
        path = destination / name
        payload = path.read_bytes()
        if len(payload) != identity['bytes']:
            raise ValueError('The restored byte count differs: ' + name)
        if hashlib.sha256(payload).hexdigest() != identity['sha256']:
            raise ValueError('The restored hash differs: ' + name)
        if stat.S_IMODE(path.stat().st_mode) != modes[name]:
            raise ValueError('The restored mode differs: ' + name)
    return {'passed': True, 'restored_files': len(restored), 'restored_bytes': total,
            'path_set_equal': True, 'byte_counts_equal': True, 'sha256_equal': True,
            'modes_equal': True, 'links_present': False}

if __name__ == '__main__':
    print(json.dumps(restore(*sys.argv[1:]), sort_keys=True))
